using Avalonia.Controls;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop; public sealed partial class ManagerFeatureManagementWindow : Window { private readonly IFeatureManager manager; private readonly Guid organizationId; public ManagerFeatureManagementWindow() => throw new InvalidOperationException("Feature runtime is required."); public ManagerFeatureManagementWindow(IFeatureManager manager, Guid organizationId) { this.manager = manager ?? throw new ArgumentNullException(nameof(manager)); if (organizationId == Guid.Empty) throw new ArgumentException("Organization is required."); this.organizationId = organizationId; InitializeComponent(); ScopeText.Text = $"Organization {organizationId:D}"; } private async void EvaluateClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Execute(Evaluate); private async void EnableClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Change(true); private async void DisableClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Change(false); private async Task Evaluate() { var v = await manager.EvaluateAsync(organizationId, KeyBox.Text ?? "", default); DecisionText.Text = $"{v.Key}: {(v.Enabled ? "Enabled" : "Disabled")} · {v.Source} · {v.EvaluatedAt:u}"; } private async Task Change(bool enabled) { var v = await manager.OverrideAsync(organizationId, KeyBox.Text ?? "", enabled, ReasonBox.Text ?? "", default); DecisionText.Text = $"{v.Key}: {(v.Enabled ? "Enabled" : "Disabled")} · override · {v.UpdatedAt:u}"; } private async Task Execute(Func<Task> a) { try { await a(); MessageText.Text = ""; } catch (Exception ex) when (ex is ArgumentException or InvalidOperationException or HttpRequestException) { MessageText.Text = ex is HttpRequestException ? "Feature service request failed." : ex.Message; } } }
